# Generated by OrchestKit Claude Plugin
# Created: 2026-07-02

"""
Academic Writer — AI Typography Fix Library

Deterministic (non-LLM) fix functions for the mechanical typography tells
left behind by LLM generation: em/en-dashes used as parenthetical breaks,
curly/straight quote mismatches across script direction, RTL punctuation-order
mistakes in Hebrew, and stray Unicode directional-formatting characters.

Used by scripts/detect-ai-typography.py. No third-party dependencies.
"""

from __future__ import annotations

import json
import re
import unicodedata
from pathlib import Path

EM_DASH = "—"
EN_DASH = "–"

HEBREW_RANGE = r"֐-׿"
HEBREW_CHAR_RE = re.compile(f"[{HEBREW_RANGE}]")
HEBREW_RUN_RE = re.compile(f"[{HEBREW_RANGE}]+")
LATIN_RUN_RE = re.compile(r"[A-Za-z]+")

GERSHAYIM = "״"
GERESH = "׳"
STRAIGHT_DQUOTE = '"'
CURLY_OPEN_DQUOTE = "“"
CURLY_CLOSE_DQUOTE = "”"

# Stray Unicode bidi/formatting control characters that should never survive
# into finished academic prose (LRM, RLM, ALM, LRE/RLE/PDF, LRO/RLO, LRI/RLI/FSI/PDI).
DIRECTIONAL_MARKS_RE = re.compile("[‎‏؜‪‫‬‭‮⁦⁧⁨⁩]")

TERMINAL_PUNCT = "?!."
DASH_REPLACEMENTS = {
    "hyphen": "-",
    "comma": ",",
    "colon": ":",
    "remove": "",
}


def load_default_dash_replacement(script_dir: Path) -> str:
    """Read typography.dashReplacement from thresholds.json, resolved
    relative to the calling script's directory (src/scripts/ or the built
    plugin's scripts/ dir — thresholds.json is always one level up in both
    layouts). Falls back to "hyphen" if unreadable — never raises."""
    candidates = [script_dir.parent / "thresholds.json", script_dir / "thresholds.json"]
    for candidate in candidates:
        try:
            data = json.loads(candidate.read_text(encoding="utf-8"))
            value = data.get("typography", {}).get("dashReplacement")
            if value in DASH_REPLACEMENTS:
                return value
        except (OSError, json.JSONDecodeError, AttributeError):
            continue
    return "hyphen"


def fix_dashes(text: str, replacement_key: str) -> tuple[str, list[dict]]:
    """Fix em-dashes and en-dashes.

    - Em-dash (—) is always an AI/English typographic tell in Hebrew academic
      prose and is replaced per `replacement_key`.
    - En-dash (–) is the correct, documented convention for numeric page/verse
      ranges (anti-ai-patterns-hebrew.md section J: "עמ' N–M"). An en-dash
      flanked by digits on both sides is left untouched; any other en-dash
      (used as a parenthetical break) is fixed the same way as an em-dash.
    """
    replacement = DASH_REPLACEMENTS[replacement_key]
    fixes: list[dict] = []
    out_chars: list[str] = []
    n = len(text)
    for i, ch in enumerate(text):
        if ch == EM_DASH:
            fixes.append(
                {
                    "type": "em_dash",
                    "original": ch,
                    "replacement": replacement,
                    "position": i,
                }
            )
            out_chars.append(replacement)
            continue
        if ch == EN_DASH:
            prev_ch = text[i - 1] if i > 0 else ""
            next_ch = text[i + 1] if i + 1 < n else ""
            if prev_ch.isdigit() and next_ch.isdigit():
                out_chars.append(ch)
                continue
            fixes.append(
                {
                    "type": "en_dash",
                    "original": ch,
                    "replacement": replacement,
                    "position": i,
                }
            )
            out_chars.append(replacement)
            continue
        out_chars.append(ch)
    return "".join(out_chars), fixes


def _looks_like_abbreviation(inner: str) -> bool:
    """A short run of Hebrew letters with no internal whitespace (e.g. an
    acronym like תנ״ך) reads as an abbreviation, not a quoted phrase."""
    return (
        bool(inner)
        and len(inner) <= 5
        and HEBREW_CHAR_RE.match(inner[0]) is not None
        and " " not in inner
    )


def fix_quotes(text: str) -> tuple[str, list[dict]]:
    """Normalize quotation marks per detected script inside each quoted span:

    - Hebrew, acronym-shaped -> gershayim (or geresh for a single letter).
    - Hebrew, phrase-shaped -> straight double quote.
    - Latin/English -> curly typographer's quotes.
    - Mixed/neither -> straight double quote (safe default).
    """
    fixes: list[dict] = []
    span_re = re.compile(r'(["\'“”‘’])([^"\'“”‘’\n]*)(["\'“”‘’])')

    result: list[str] = []
    last_end = 0
    for m in span_re.finditer(text):
        opener, inner, closer = m.group(1), m.group(2), m.group(3)
        start, end = m.start(), m.end()
        if not inner:
            continue

        has_hebrew = bool(HEBREW_RUN_RE.search(inner))
        has_latin = bool(LATIN_RUN_RE.search(inner))

        if has_hebrew and not has_latin:
            new_open = new_close = (
                GERESH
                if len(inner) == 1
                else (GERSHAYIM if _looks_like_abbreviation(inner) else STRAIGHT_DQUOTE)
            )
        elif has_latin and not has_hebrew:
            new_open, new_close = CURLY_OPEN_DQUOTE, CURLY_CLOSE_DQUOTE
        else:
            new_open = new_close = STRAIGHT_DQUOTE

        replaced_any = False
        if opener != new_open:
            fixes.append(
                {
                    "type": "quote_normalize",
                    "original": opener,
                    "replacement": new_open,
                    "position": start,
                }
            )
            replaced_any = True
        if closer != new_close:
            fixes.append(
                {
                    "type": "quote_normalize",
                    "original": closer,
                    "replacement": new_close,
                    "position": end - 1,
                }
            )
            replaced_any = True

        if replaced_any:
            result.append(text[last_end:start])
            result.append(new_open + inner + new_close)
            last_end = end

    result.append(text[last_end:])
    return "".join(result), fixes


def _fix_leading_terminal_punctuation(
    segment: str, base_offset: int, fixes: list[dict]
) -> str:
    stripped = segment.lstrip()
    leading_ws = segment[: len(segment) - len(stripped)]
    if not stripped or stripped[0] not in TERMINAL_PUNCT:
        return segment
    mark = stripped[0]
    rest = stripped[1:]
    if not HEBREW_CHAR_RE.search(rest):
        return segment
    rest_stripped = rest.rstrip()
    trailing_ws = rest[len(rest_stripped) :]
    if not rest_stripped or rest_stripped.endswith(mark):
        return segment
    fixes.append(
        {
            "type": "leading_terminal_punctuation",
            "original": mark + rest_stripped[:1],
            "replacement": mark,
            "position": base_offset + len(leading_ws),
        }
    )
    return f"{leading_ws}{rest_stripped}{mark}{trailing_ws}"


def fix_rtl_punctuation(text: str) -> tuple[str, list[dict]]:
    """Fix RTL punctuation-order problems in Hebrew sentences/lines:

    1. Reversed parenthesis pairs around Hebrew content — ")text(" instead
       of "(text)" — are swapped back to logical order (Unicode's bidi
       algorithm auto-mirrors bracket glyphs for RTL rendering, so the
       *logical* order must always be open-then-close).
    2. A terminal mark (?, !, .) stranded at the logical start of a Hebrew
       sentence/line is moved to the logical end.
    """
    fixes: list[dict] = []

    paren_re = re.compile(r"\)([^()\n]*)\(")

    def _paren_repl(m: re.Match) -> str:
        inner = m.group(1)
        if HEBREW_CHAR_RE.search(inner):
            fixes.append(
                {
                    "type": "reversed_parens",
                    "original": m.group(0),
                    "replacement": f"({inner})",
                    "position": m.start(),
                }
            )
            return f"({inner})"
        return m.group(0)

    text = paren_re.sub(_paren_repl, text)

    out_lines = []
    offset = 0
    for line in text.split("\n"):
        pieces = re.split(r"(?<=[.!?])\s+", line)
        fixed_pieces = []
        piece_offset = offset
        for piece in pieces:
            fixed_pieces.append(
                _fix_leading_terminal_punctuation(piece, piece_offset, fixes)
            )
            piece_offset += len(piece) + 1
        fixed_line = (
            " ".join(fixed_pieces)
            if len(pieces) > 1
            else (fixed_pieces[0] if fixed_pieces else line)
        )
        out_lines.append(fixed_line)
        offset += len(line) + 1

    return "\n".join(out_lines), fixes


def fix_directional_marks(text: str) -> tuple[str, list[dict]]:
    """Strip stray bidi/directional-formatting control characters."""
    fixes: list[dict] = []
    out_chars: list[str] = []
    for i, ch in enumerate(text):
        if DIRECTIONAL_MARKS_RE.match(ch):
            fixes.append(
                {
                    "type": "directional_mark",
                    "original": f"U+{ord(ch):04X} ({unicodedata.name(ch, 'UNKNOWN')})",
                    "replacement": "",
                    "position": i,
                }
            )
            continue
        out_chars.append(ch)
    return "".join(out_chars), fixes


def run(
    text: str,
    dash_replacement: str,
    do_dashes: bool = True,
    do_quotes: bool = True,
    do_rtl: bool = True,
    do_directional: bool = True,
) -> dict:
    """Run the enabled fix categories in a fixed, deterministic order and
    return {"fixed_text": ..., "fixes": [...]}."""
    all_fixes: list[dict] = []
    working = text

    if do_directional:
        working, fixes = fix_directional_marks(working)
        all_fixes.extend(fixes)

    if do_dashes:
        working, fixes = fix_dashes(working, dash_replacement)
        all_fixes.extend(fixes)

    if do_quotes:
        working, fixes = fix_quotes(working)
        all_fixes.extend(fixes)

    if do_rtl:
        working, fixes = fix_rtl_punctuation(working)
        all_fixes.extend(fixes)

    return {"fixed_text": working, "fixes": all_fixes}
